 80	McpSetupResult run_mcp_setup_command(wxWindow* parent, const std::vector<std::string>& arguments)
 81	{
 82	    if (arguments.empty()) throw std::invalid_argument("Missing setup executable");
 83	    wxDialog progress(parent, wxID_ANY, "Connecting AI tool", wxDefaultPosition, parent->FromDIP(wxSize(460, 140)));
 84	    auto* label = new wxStaticText(&progress, wxID_ANY, "Saving the MCP entry using the client's own CLI...");
 85	    auto* layout = new wxBoxSizer(wxVERTICAL);
 86	    layout->Add(label, 1, wxEXPAND | wxALL, progress.FromDIP(16));
 87	    progress.SetSizer(layout);
 88	    wxProcess process(&progress);
 89	    process.Redirect();
 90	    std::vector<wxString> values;
 91	    for (const auto& value : arguments) values.push_back(wxString::FromUTF8(value));
 92	    std::vector<const wchar_t*> argv;
 93	    for (const auto& value : values) argv.push_back(value.wc_str());
 94	    argv.push_back(nullptr);
 95	    const auto pid = wxExecute(argv.data(), wxEXEC_ASYNC | wxEXEC_HIDE_CONSOLE, &process);
 96	    if (pid <= 0) return {false, "Could not start the client CLI. Use Copy or check its installation."};
 97	    process.CloseOutput();
 98	    std::string output;
 99	    bool timed_out = false;
100	    int exit_code = -1;
101	    const auto started = std::chrono::steady_clock::now();
102	    auto drain = [&] {
103	        for (auto* stream : {process.GetInputStream(), process.GetErrorStream()}) {
104	            while (stream && stream->CanRead()) {
105	                char buffer[4096];
106	                stream->Read(buffer, sizeof buffer);
107	                const auto size = stream->LastRead();
108	                if (!size) break;
109	                if (output.size() < 65536) output.append(buffer, std::min(size, 65536 - output.size()));
110	            }
111	        }
112	    };
113	    wxTimer timer(&progress);
114	    progress.Bind(wxEVT_TIMER, [&](wxTimerEvent&) {
115	        drain();
116	        const auto elapsed = std::chrono::steady_clock::now() - started;
117	        if (!timed_out && elapsed > std::chrono::seconds(30)) {
118	            timed_out = true;
119	            label->SetLabel("The setup command timed out. Stopping it...");
120	            wxProcess::Kill(pid, wxSIGTERM);
121	        } else if (timed_out && elapsed > std::chrono::seconds(32)) wxProcess::Kill(pid, wxSIGKILL);
122	    });
123	    progress.Bind(wxEVT_CLOSE_WINDOW, [&](wxCloseEvent& event) {
124	        if (event.CanVeto()) event.Veto(); // Keep the owned process alive only while its monitor exists.
125	    });
126	    // wxDialog handles Cancel separately from window-close events. Do not
127	    // destroy the process monitor while the CLI may still be saving settings.
128	    progress.Bind(wxEVT_BUTTON, [](wxCommandEvent&) {}, wxID_CANCEL);
129	    progress.Bind(wxEVT_END_PROCESS, [&](wxProcessEvent& event) {
130	        drain(); exit_code = event.GetExitCode(); timer.Stop(); progress.EndModal(wxID_OK);
131	    });
132	    timer.Start(30);
133	    progress.ShowModal();
134	    if (timed_out) return {false, "Setup timed out; the client config may have changed. Inspect it before trying again.\n" + output};
135	    return {exit_code == 0, "Client CLI exited with code " + std::to_string(exit_code) + ".\n" + output};
136	}
137	
138	void start_mcp_setup_command(wxWindow* parent, const std::vector<std::string>& arguments,
139	                             std::function<void(McpSetupResult)> done)
140	{
141	    if (arguments.empty()) {
142	        done({false, "Missing setup executable"});
143	        return;
144	    }
145	    struct Watch : wxEvtHandler {
146	        wxProcess process;
147	        wxTimer timer;
148	        std::function<void(McpSetupResult)> done;
149	        std::string output;
150	        std::chrono::steady_clock::time_point started;
151	        long pid{0};
152	        bool timed_out{false};
153	        bool finished{false};
154	        Watch(wxWindow*, std::function<void(McpSetupResult)> complete)
155	            : process(this), timer(this), done(std::move(complete)), started(std::chrono::steady_clock::now())
156	        {}
157	        void drain()
158	        {
159	            for (auto* stream : {process.GetInputStream(), process.GetErrorStream()}) {
160	                while (stream && stream->CanRead()) {
161	                    char buffer[4096];
162	                    stream->Read(buffer, sizeof buffer);
163	                    const auto size = stream->LastRead();
164	                    if (!size) break;
165	                    if (output.size() < 65536) output.append(buffer, std::min(size, 65536 - output.size()));
166	                }
167	            }
168	        }
169	        void finish(McpSetupResult result)
170	        {
171	            if (finished) return;
172	            finished = true;
173	            timer.Stop();
174	            auto complete = std::move(done);
175	            complete(std::move(result));
176	            CallAfter([this] { delete this; });
177	        }
178	    };
179	    auto* watch = new Watch(parent, std::move(done));
180	    std::vector<wxString> values;
181	    for (const auto& value : arguments) values.push_back(wxString::FromUTF8(value));
182	    std::vector<const wchar_t*> argv;
183	    for (const auto& value : values) argv.push_back(value.wc_str());
184	    argv.push_back(nullptr);
185	    watch->pid = wxExecute(argv.data(), wxEXEC_ASYNC | wxEXEC_HIDE_CONSOLE, &watch->process);
186	    if (watch->pid <= 0) {
187	        watch->finish({false, "Could not start the client CLI. Use Copy or check its installation."});
188	        return;
189	    }
190	    watch->process.CloseOutput();
191	    watch->Bind(wxEVT_TIMER, [watch](wxTimerEvent&) {
192	        watch->drain();
193	        const auto elapsed = std::chrono::steady_clock::now() - watch->started;
194	        if (!watch->timed_out && elapsed > std::chrono::seconds(30)) {
195	            watch->timed_out = true;
196	            wxProcess::Kill(watch->pid, wxSIGTERM);
197	        } else if (watch->timed_out && elapsed > std::chrono::seconds(32))
198	            wxProcess::Kill(watch->pid, wxSIGKILL);
199	    });
200	    watch->Bind(wxEVT_END_PROCESS, [watch](wxProcessEvent& event) {
201	        if (event.GetPid() != watch->pid) { event.Skip(); return; }
202	        watch->drain();
203	        if (watch->timed_out)
204	            watch->finish({false, "Setup timed out; the client config may have changed. Inspect it before trying again.\n" + watch->output});
205	        else
206	            watch->finish({event.GetExitCode() == 0,
207	                           "Client CLI exited with code " + std::to_string(event.GetExitCode()) + ".\n" + watch->output});
208	    });
209	    watch->timer.Start(30);
210	}
211	
212	void show_mcp_connection_dialog(wxWindow* parent, const ShellTheme& theme, const std::string& discovery_path,
213	                                const std::string& live_url, const std::string& startup_error)
214	{
215	#ifdef _WIN32
216	    constexpr bool windows = true;
217	    const std::string helper_name = "jusprin-mcp.exe";
218	#else
219	    constexpr bool windows = false;
220	    const std::string helper_name = "jusprin-mcp";
221	#endif
222	    const auto executable = std::filesystem::u8path(utf8(wxStandardPaths::Get().GetExecutablePath()));
223	    const auto bridge = executable.parent_path() / helper_name;
224	    auto launcher = bridge;
225	    std::vector<std::string> launch_arguments;
226	#if defined(__linux__)
227	    wxString appimage;
228	    if (wxGetEnv("APPIMAGE", &appimage) && !appimage.empty()) {
229	        launcher = std::filesystem::u8path(utf8(appimage));
230	        launch_arguments.emplace_back("--mcp-bridge");
231	    }
232	#endif
233	    const auto entries = Mcp::connection_entries(launcher.u8string(), discovery_path, windows, launch_arguments);
234	    const auto home = std::filesystem::u8path(utf8(wxGetHomeDir()));
235	#ifdef __APPLE__
236	    const auto config_home = home / "Library" / "Application Support";
237	#elif defined(_WIN32)
238	    wxString appdata;
239	    wxGetEnv("APPDATA", &appdata);
240	    const auto config_home = std::filesystem::u8path(utf8(appdata));
241	#else
242	    wxString xdg;
243	    wxGetEnv("XDG_CONFIG_HOME", &xdg);
244	    const auto config_home = xdg.empty() ? home / ".config" : std::filesystem::u8path(utf8(xdg));
245	#endif
246	    const std::vector<std::filesystem::path> configs{
247	        home / ".claude.json", home / ".codex" / "config.toml",
248	        config_home / "Claude" / "claude_desktop_config.json",
249	        config_home / "Claude" / "claude_desktop_config.json",
250	        home / ".cursor" / "mcp.json", config_home / "Code" / "User" / "mcp.json"
251	    };
252	    wxDialog dialog(parent, wxID_ANY, "Connect AI tools", wxDefaultPosition, parent->FromDIP(wxSize(760, 550)),
253	                    wxDEFAULT_DIALOG_STYLE | wxRESIZE_BORDER);
254	    const auto& colors = theme.palette(GUI_App::dark_mode());
255	    dialog.SetBackgroundColour(colors.surface_raised);
256	    dialog.SetForegroundColour(colors.text_primary);
257	    auto* layout = new wxBoxSizer(wxVERTICAL);
258	    const int gap = dialog.FromDIP(12);
259	    auto* intro = new wxStaticText(&dialog, wxID_ANY,
260	        "Connect a local AI tool to the open JusPrin project. Changes still require approval in the Agent panel.\n"
261	        "Copy the entry, or choose Connect and review the proposed change before saving it.");
262	    style_label(*intro, theme, TextRole::Body, colors.text_primary);
263	    intro->Wrap(dialog.FromDIP(710));
264	    layout->Add(intro, 0, wxEXPAND | wxALL, gap);
265	    auto* clients = new wxChoice(&dialog, wxID_ANY);
266	    for (std::size_t i = 0; i < entries.size(); ++i) {
267	        std::error_code error;
268	        const bool detected = std::filesystem::exists(configs[i], error) || !command_path(entries[i].id).empty();
269	        clients->Append(wxString::FromUTF8((detected ? "Detected: " : "Other: ") + entries[i].name));
270	    }
271	    clients->SetSelection(0);
272	    clients->SetName("MCP client");
273	    layout->Add(clients, 0, wxEXPAND | wxLEFT | wxRIGHT, gap);
274	    auto* instructions = new wxStaticText(&dialog, wxID_ANY, "");
275	    style_label(*instructions, theme, TextRole::Body, colors.text_primary);
276	    layout->Add(instructions, 0, wxEXPAND | wxALL, gap);
277	    auto* entry = new wxTextCtrl(&dialog, wxID_ANY, "", wxDefaultPosition, wxDefaultSize,
278	                                 wxTE_MULTILINE | wxTE_READONLY);
279	    entry->SetName("MCP connection entry");
280	    style_text_field(*entry, theme, colors);
281	    layout->Add(entry, 1, wxEXPAND | wxLEFT | wxRIGHT, gap);
282	    auto* status = new wxStaticText(&dialog, wxID_ANY, "");
283	    style_label(*status, theme, TextRole::Body, colors.text_primary);
284	    layout->Add(status, 0, wxEXPAND | wxALL, gap);
285	    auto refresh = [&] {
286	        const auto index = std::size_t(clients->GetSelection());
287	        const auto& selected = entries[index];
288	        std::string guidance = selected.cli ? (windows ? "Run in PowerShell." : "Run in your terminal.") :
289	            "Merge this entry into " + configs[index].u8string() + ". Keep existing servers and settings.";
290	        if (selected.id == "cowork") guidance += " Requires a local Cowork session; cloud sessions cannot reach this helper.";
291	        if (selected.id == "codex") guidance += " For approvals longer than 60 seconds, raise tool_timeout_sec in the JusPrin MCP config.";
292	        instructions->SetLabel(wxString::FromUTF8(guidance));
293	        instructions->Wrap(dialog.FromDIP(710));
294	        entry->SetValue(wxString::FromUTF8(selected.text));
295	        status->SetLabel("");
296	        dialog.Layout();
297	    };
298	    clients->Bind(wxEVT_CHOICE, [&](wxCommandEvent&) { refresh(); });
299	    auto* disclosure = new wxCollapsiblePane(&dialog, wxID_ANY, "Direct HTTP (developer use)");
300	    auto* details = new wxBoxSizer(wxVERTICAL);
301	    const auto diagnostic = live_url.empty() ? "MCP could not start: " + startup_error :
302	        live_url + "\nThis URL can change after restarting JusPrin. Local requests need no authentication.";
303	    auto* diagnostics = new wxTextCtrl(disclosure->GetPane(), wxID_ANY, wxString::FromUTF8(diagnostic), wxDefaultPosition,
304	                                       dialog.FromDIP(wxSize(-1, 70)), wxTE_MULTILINE | wxTE_READONLY);
305	    style_text_field(*diagnostics, theme, colors);
306	    details->Add(diagnostics, 1, wxEXPAND);
307	    disclosure->GetPane()->SetSizer(details);
308	    disclosure->Bind(wxEVT_COLLAPSIBLEPANE_CHANGED, [&](wxCollapsiblePaneEvent&) { dialog.Layout(); });
309	    layout->Add(disclosure, 0, wxEXPAND | wxLEFT | wxRIGHT, gap);
310	    auto* buttons = new wxBoxSizer(wxHORIZONTAL);
311	    auto* copy = new wxButton(&dialog, wxID_ANY, "Copy");
312	    copy->Bind(wxEVT_BUTTON, [&](wxCommandEvent&) {
313	        if (!wxTheClipboard->Open()) { status->SetLabel("Clipboard is busy. Try Copy again."); return; }
314	        const bool copied = wxTheClipboard->SetData(new wxTextDataObject(entry->GetValue()));
315	        wxTheClipboard->Close();
316	        status->SetLabel(copied ? "Copied. No client settings were changed." : "Could not copy the entry.");
317	    });
318	    buttons->Add(copy);
319	    auto* connect = new wxButton(&dialog, wxID_ANY, "Connect...");
320	    connect->Bind(wxEVT_BUTTON, [&](wxCommandEvent&) {
321	        const auto index = std::size_t(clients->GetSelection());
322	        const auto& selected = entries[index];
323	        try {
324	            if (!std::filesystem::is_regular_file(bridge))
325	                throw std::runtime_error("The bundled MCP helper is missing. Reinstall or rebuild JusPrin.");
326	            if (!std::filesystem::is_regular_file(launcher))
327	                throw std::runtime_error("The AppImage launcher is missing. Reopen the installed AppImage.");
328	            if (selected.cli) {
329	                const auto cli = command_path(selected.id);
330	                if (cli.empty()) throw std::runtime_error("Client CLI was not found. Install it or use Copy in your terminal.");
331	                std::vector<std::string> arguments{cli};
332	                arguments.insert(arguments.end(), selected.arguments.begin(), selected.arguments.end());
333	                std::string command;
334	                for (const auto& argument : arguments) command += (command.empty() ? "" : " ") + Mcp::quote_argument(argument, windows);
335	                if (!confirm_setup(&dialog, theme, colors, "Run this command directly (no shell):\n\n" + command +
336	                    "\n\nThe client CLI manages its configuration. It may replace an existing JusPrin entry. Other servers are not removed.")) return;
337	                const auto result = run_mcp_setup_command(&dialog, arguments);
338	                status->SetLabel(wxString::FromUTF8((result.success ? "Configuration saved. Restart the client session to load JusPrin.\n" : "Setup failed.\n") + result.diagnostic));
339	            } else {
340	                const std::string root = selected.id == "code" ? "servers" : "mcpServers";
341	                const auto value = nlohmann::json::parse(selected.text);
342	                const auto edit = Mcp::prepare_json_connection(configs[index], root, value[root]["jusprin"]);
343	                if (!confirm_setup(&dialog, theme, colors, edit.preview)) return;
344	                const auto backup = Mcp::apply_config_edit(edit);
345	                status->SetLabel(wxString::FromUTF8("Configuration saved. Restart the client to load JusPrin." +
346	                    (backup.empty() ? "" : "\nBackup: " + backup.u8string())));
347	            }
348	        } catch (const std::exception& error) {
349	            // Client setup is an independent user operation. Show its failure;
350	            // keep the slicer usable and never report an unsuccessful write as connected.
351	            status->SetLabel(wxString::FromUTF8(std::string("Could not configure client: ") + error.what()));
352	        }
353	        status->Wrap(dialog.FromDIP(710));
354	        dialog.Layout();
355	    });
356	    buttons->Add(connect, 0, wxLEFT, gap);
357	    buttons->AddStretchSpacer();
358	    buttons->Add(new wxButton(&dialog, wxID_OK, "Close"));
359	    layout->Add(buttons, 0, wxEXPAND | wxALL, gap);
360	    dialog.SetSizer(layout);
361	    refresh();
362	    if (!std::filesystem::is_regular_file(bridge)) status->SetLabel("The bundled MCP helper is missing. Reinstall or rebuild JusPrin.");
363	    dialog.SetMinSize(dialog.FromDIP(wxSize(580, 440)));
364	    dialog.ShowModal();
365	}
366	} // namespace Slic3r::GUI::JusPrin

