 27	std::string utf8(const wxString& value) { return value.ToUTF8().data(); }
 28	
 29	std::string command_path(const std::string& command)
 30	{
 31	    wxString path;
 32	    wxGetEnv("PATH", &path);
 33	#ifdef _WIN32
 34	    wxStringTokenizer directories(path, ";");
 35	    const auto filename = wxString::FromUTF8(command + ".exe");
 36	#else
 37	    wxStringTokenizer directories(path, ":");
 38	    const auto filename = wxString::FromUTF8(command);
 39	#endif
 40	    while (directories.HasMoreTokens()) {
 41	        const auto directory = directories.GetNextToken();
 42	        const auto candidate = wxFileName(directory, filename).GetFullPath();
 43	        if (!directory.empty() && wxFileName::IsFileExecutable(candidate)) return utf8(candidate);
 44	    }
 45	    // GUI launches on macOS often inherit a shorter PATH than a login shell.
 46	#ifndef _WIN32
 47	    for (const auto& directory : {wxGetHomeDir() + "/.local/bin", wxString("/opt/homebrew/bin"), wxString("/usr/local/bin")}) {
 48	        const auto candidate = wxFileName(directory, filename).GetFullPath();
 49	        if (wxFileName::IsFileExecutable(candidate)) return utf8(candidate);
 50	    }
 51	#endif
 52	    return {};
 53	}
