 55	bool confirm_setup(wxWindow* parent, const ShellTheme& theme, const ShellPalette& colors, const std::string& preview)
 56	{
 57	    wxDialog dialog(parent, wxID_ANY, "Confirm AI tool connection", wxDefaultPosition, parent->FromDIP(wxSize(740, 520)),
 58	                    wxDEFAULT_DIALOG_STYLE | wxRESIZE_BORDER);
 59	    dialog.SetBackgroundColour(colors.surface_raised);
 60	    auto* layout = new wxBoxSizer(wxVERTICAL);
 61	    auto* question = new wxStaticText(&dialog, wxID_ANY,
 62	        "Allow this AI tool to read the open project and propose changes?\nChanges still require approval inside JusPrin.");
 63	    style_label(*question, theme, TextRole::Body, colors.text_primary);
 64	    layout->Add(question, 0, wxEXPAND | wxALL, dialog.FromDIP(12));
 65	    auto* text = new wxTextCtrl(&dialog, wxID_ANY, wxString::FromUTF8(preview), wxDefaultPosition, wxDefaultSize,
 66	                                wxTE_MULTILINE | wxTE_READONLY);
 67	    style_text_field(*text, theme, colors);
 68	    layout->Add(text, 1, wxEXPAND | wxLEFT | wxRIGHT, dialog.FromDIP(12));
 69	    auto* buttons = new wxStdDialogButtonSizer;
 70	    auto* confirm = new wxButton(&dialog, wxID_OK, "Connect");
 71	    auto* cancel = new wxButton(&dialog, wxID_CANCEL, "Cancel");
 72	    buttons->AddButton(confirm); buttons->AddButton(cancel); buttons->Realize();
 73	    cancel->SetDefault();
 74	    layout->Add(buttons, 0, wxALIGN_RIGHT | wxALL, dialog.FromDIP(12));
 75	    dialog.SetSizer(layout);
 76	    return dialog.ShowModal() == wxID_OK;
 77	}
