12	namespace Slic3r::GUI::JusPrin {
13	
14	McpSetupResult run_mcp_setup_command(wxWindow* parent, const std::vector<std::string>& arguments)
15	{
16	    if (arguments.empty()) throw std::invalid_argument("Missing setup executable");
17	    wxDialog progress(parent, wxID_ANY, "Connecting AI tool", wxDefaultPosition, parent->FromDIP(wxSize(460, 140)));
18	    auto* label = new wxStaticText(&progress, wxID_ANY, "Saving the MCP entry using the client's own CLI...");
19	    auto* layout = new wxBoxSizer(wxVERTICAL);
20	    layout->Add(label, 1, wxEXPAND | wxALL, progress.FromDIP(16));
21	    progress.SetSizer(layout);
22	    wxProcess process(&progress);
23	    process.Redirect();
24	    std::vector<wxString> values;
25	    for (const auto& value : arguments) values.push_back(wxString::FromUTF8(value));
26	    std::vector<const wchar_t*> argv;
27	    for (const auto& value : values) argv.push_back(value.wc_str());
28	    argv.push_back(nullptr);
29	    const auto pid = wxExecute(argv.data(), wxEXEC_ASYNC | wxEXEC_HIDE_CONSOLE, &process);
30	    if (pid <= 0) return {false, "Could not start the client CLI. Use Copy or check its installation."};
31	    process.CloseOutput();
32	    std::string output;
33	    bool timed_out = false;
34	    int exit_code = -1;
35	    const auto started = std::chrono::steady_clock::now();
36	    auto drain = [&] {
37	        for (auto* stream : {process.GetInputStream(), process.GetErrorStream()}) {
38	            while (stream && stream->CanRead()) {
39	                char buffer[4096];
40	                stream->Read(buffer, sizeof buffer);
41	                const auto size = stream->LastRead();
42	                if (!size) break;
43	                if (output.size() < 65536) output.append(buffer, std::min(size, 65536 - output.size()));
44	            }
45	        }
46	    };
47	    wxTimer timer(&progress);
48	    progress.Bind(wxEVT_TIMER, [&](wxTimerEvent&) {
49	        drain();
50	        const auto elapsed = std::chrono::steady_clock::now() - started;
51	        if (!timed_out && elapsed > std::chrono::seconds(30)) {
52	            timed_out = true;
53	            label->SetLabel("The setup command timed out. Stopping it...");
54	            wxProcess::Kill(pid, wxSIGTERM);
55	        } else if (timed_out && elapsed > std::chrono::seconds(32)) wxProcess::Kill(pid, wxSIGKILL);
56	    });
57	    progress.Bind(wxEVT_CLOSE_WINDOW, [&](wxCloseEvent& event) {
58	        if (event.CanVeto()) event.Veto(); // Keep the owned process alive only while its monitor exists.
59	    });
60	    // wxDialog handles Cancel separately from window-close events. Do not
61	    // destroy the process monitor while the CLI may still be saving settings.
62	    progress.Bind(wxEVT_BUTTON, [](wxCommandEvent&) {}, wxID_CANCEL);
63	    progress.Bind(wxEVT_END_PROCESS, [&](wxProcessEvent& event) {
64	        drain(); exit_code = event.GetExitCode(); timer.Stop(); progress.EndModal(wxID_OK);
65	    });
66	    timer.Start(30);
67	    progress.ShowModal();
68	    if (timed_out) return {false, "Setup timed out; the client config may have changed. Inspect it before trying again.\n" + output};
69	    return {exit_code == 0, "Client CLI exited with code " + std::to_string(exit_code) + ".\n" + output};
70	}
71	
72	void start_mcp_setup_command(wxWindow* parent, const std::vector<std::string>& arguments,
73	                             std::function<void(McpSetupResult)> done)
74	{
75	    if (arguments.empty()) {
76	        done({false, "Missing setup executable"});
77	        return;
78	    }
79	    struct Watch : wxEvtHandler {
80	        wxProcess process;
81	        wxTimer timer;
82	        std::function<void(McpSetupResult)> done;
83	        std::string output;
84	        std::chrono::steady_clock::time_point started;
85	        long pid{0};
86	        bool timed_out{false};
87	        bool finished{false};
88	        Watch(wxWindow*, std::function<void(McpSetupResult)> complete)
89	            : process(this), timer(this), done(std::move(complete)), started(std::chrono::steady_clock::now())
90	        {}
91	        void drain()
92	        {
93	            for (auto* stream : {process.GetInputStream(), process.GetErrorStream()}) {
94	                while (stream && stream->CanRead()) {
95	                    char buffer[4096];
96	                    stream->Read(buffer, sizeof buffer);
97	                    const auto size = stream->LastRead();
98	                    if (!size) break;
99	                    if (output.size() < 65536) output.append(buffer, std::min(size, 65536 - output.size()));
100	                }
101	            }
102	        }
103	        void finish(McpSetupResult result)
104	        {
105	            if (finished) return;
106	            finished = true;
107	            timer.Stop();
108	            auto complete = std::move(done);
109	            complete(std::move(result));
110	            CallAfter([this] { delete this; });
111	        }
112	    };
113	    auto* watch = new Watch(parent, std::move(done));
114	    std::vector<wxString> values;
115	    for (const auto& value : arguments) values.push_back(wxString::FromUTF8(value));
116	    std::vector<const wchar_t*> argv;
117	    for (const auto& value : values) argv.push_back(value.wc_str());
118	    argv.push_back(nullptr);
119	    watch->pid = wxExecute(argv.data(), wxEXEC_ASYNC | wxEXEC_HIDE_CONSOLE, &watch->process);
120	    if (watch->pid <= 0) {
121	        watch->finish({false, "Could not start the client CLI. Use Copy or check its installation."});
122	        return;
123	    }
124	    watch->process.CloseOutput();
125	    watch->Bind(wxEVT_TIMER, [watch](wxTimerEvent&) {
126	        watch->drain();
127	        const auto elapsed = std::chrono::steady_clock::now() - watch->started;
128	        if (!watch->timed_out && elapsed > std::chrono::seconds(30)) {
129	            watch->timed_out = true;
130	            wxProcess::Kill(watch->pid, wxSIGTERM);
131	        } else if (watch->timed_out && elapsed > std::chrono::seconds(32))
132	            wxProcess::Kill(watch->pid, wxSIGKILL);
133	    });
134	    watch->Bind(wxEVT_END_PROCESS, [watch](wxProcessEvent& event) {
135	        if (event.GetPid() != watch->pid) { event.Skip(); return; }
136	        watch->drain();
137	        if (watch->timed_out)
138	            watch->finish({false, "Setup timed out; the client config may have changed. Inspect it before trying again.\n" + watch->output});
139	        else
140	            watch->finish({event.GetExitCode() == 0,
141	                           "Client CLI exited with code " + std::to_string(event.GetExitCode()) + ".\n" + watch->output});
142	    });
143	    watch->timer.Start(30);
144	}
145	} // namespace Slic3r::GUI::JusPrin

